CREATE TABLE Product(id INTEGER PRIMARY KEY, qty INTEGER NOT NULL);
CREATE TABLE Audit(product_id INTEGER NOT NULL, old_qty INTEGER NOT NULL, new_qty INTEGER NOT NULL);
INSERT INTO Product VALUES(1,3),(2,8);
CREATE TRIGGER qty_audit AFTER UPDATE OF qty ON Product
FOR EACH ROW WHEN OLD.qty<>NEW.qty
BEGIN
  INSERT INTO Audit VALUES(NEW.id,OLD.qty,NEW.qty);
END;
UPDATE Product SET qty=qty+1;
SELECT product_id,old_qty,new_qty FROM Audit ORDER BY product_id;

